#include <iostream>
#include <vector>
#include <queue>

int main() {
    std::vector<std::vector<int>> g={{1},{0,2},{1}};
    std::vector<int> dist(3,-1);
    std::queue<int> q;
    dist[0]=0; q.push(0);
    while(!q.empty()) {
        int u=q.front();q.pop();
        for(int v:g[u]) if(dist[v]==-1) {
            dist[v]=dist[u]+1;
            q.push(v);
        }
    }
    std::cout << dist[2] << "\n";
    return 0;
}

