#include <iostream>
#include <vector>
#include <queue>
#include <functional>
#include <utility>

int main() {
    using P=std::pair<long long,int>;
    std::vector<std::vector<std::pair<int,int>>> g(3);
    g[0]={{1,2},{2,10}};
    g[1]={{2,3}};
    std::vector<long long> dist(3,1000000000000LL);
    std::priority_queue<P,std::vector<P>,std::greater<P>> q;
    dist[0]=0;q.push({0,0});
    while(!q.empty()) {
        auto [d,u]=q.top();q.pop();
        if(d!=dist[u])continue;
        for(auto [v,w]:g[u]) if(d+w<dist[v]) {
            dist[v]=d+w;q.push({dist[v],v});
        }
    }
    std::cout << dist[2] << "\n";
    return 0;
}

